function main(): void {
  const f: any = undefined;
  console.log(f?.(), 1);
  try { f(); } catch (e) { console.log((e as Error).name, (e as Error).message); }
  console.log(f?.call(null));
  const g: any = null;
  console.log(g?.(2));
  try { g(); } catch (e) { console.log((e as Error).name, (e as Error).message); }
}
